<?php header('Content-Type: application/json');try{$c=require __DIR__.'/config.php';$p=new PDO("mysql:host={$c['db_host']};dbname={$c['db_name']};charset=utf8mb4",$c['db_user'],$c['db_pass'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION]);echo json_encode($p->query("SELECT id,name,category,price,icon,details FROM products WHERE active=1 ORDER BY featured DESC,id DESC")->fetchAll(PDO::FETCH_ASSOC));}catch(Throwable $e){echo json_encode([]);}